// y quien lo lee puede mandar SIGTERM en seguida.
const stop = (): void => {
  void proxy.stop().then(() => {
    opened.close()
    process.exit(0)
  })
}
process.on('SIGTERM', stop)
process.on('SIGINT', stop)
